<script>document.addEventListener('DOMContentLoaded',()=>{const outcomes=@json($outcomeMap),bodies=@json($allBodies->pluck('name','id')),levels=@json($levelText);const training=document.getElementById('certificate-training'),skill=document.getElementById('certificate-skill'),level=document.getElementById('certificate-level');function updateLevel(){level.replaceChildren(new Option('Pilih level',''));const cap=Number(skill.selectedOptions[0]?.dataset.cap||0);for(let i=1;i<=cap;i++)level.add(new Option(levels[i],i));}function update(){const id=training.value,body=training.selectedOptions[0]?.dataset.body||'';document.getElementById('certificate-body').value=body;document.getElementById('certificate-issuer').textContent='Lembaga: '+(bodies[body]||'Belum dipilih');skill.replaceChildren(new Option('Pilih skill',''));for(const o of outcomes[id]||[]){const option=new Option(o.name,o.id);option.dataset.cap=o.level;skill.add(option);}updateLevel();}training.addEventListener('change',update);skill.addEventListener('change',updateLevel);update();});</script>@endif</section>
